package tests

import (
	"errors"
	"fmt"
	"io"
	"os"
	"strings"
	"testing"

	"exercise/src/ingest"
)

type errReader struct{}

func (errReader) Read([]byte) (int, error) { return 0, errors.New("connection reset") }

type fakeSource struct {
	files    map[string]string
	failRead map[string]bool
	opened   int
	closed   int
}

type handle struct {
	io.Reader
	src    *fakeSource
	closed bool
}

func (h *handle) Close() error {
	if h.closed {
		return errors.New("double close")
	}
	h.closed = true
	h.src.closed++
	return nil
}

func (s *fakeSource) Open(name string) (io.ReadCloser, error) {
	c, ok := s.files[name]
	if !ok {
		return nil, os.ErrNotExist
	}
	s.opened++
	var r io.Reader = strings.NewReader(c)
	if s.failRead[name] {
		r = io.MultiReader(r, errReader{})
	}
	return &handle{Reader: r, src: s}, nil
}

func newSource() *fakeSource {
	return &fakeSource{
		files: map[string]string{
			"good1.csv": "ACC1,USD\n10,deposit\n-4,fee\n",
			"good2.csv": "ACC2,EUR\n5,deposit\n",
			"bad.csv":   "not a header\n1,2\n",
			"empty.csv": "",
			"cut.csv":   "ACC3,GBP\n1,x\n",
		},
		failRead: map[string]bool{"cut.csv": true},
	}
}

func TestImportCountsRows(t *testing.T) {
	src := newSource()
	res := ingest.ImportAll(src, []string{"good1.csv", "good2.csv"})
	if res[0].Err != nil || res[0].Rows != 2 || res[0].Account != "ACC1" || res[0].Currency != "USD" {
		t.Fatalf("good1: got %+v", res[0])
	}
	if res[1].Rows != 1 {
		t.Fatalf("good2 rows: want 1, got %d", res[1].Rows)
	}
}

func TestHandlesClosedOnSuccess(t *testing.T) {
	src := newSource()
	ingest.ImportAll(src, []string{"good1.csv", "good2.csv"})
	if src.opened != 2 || src.closed != 2 {
		t.Fatalf("opened %d, closed %d; want 2 and 2", src.opened, src.closed)
	}
}

func TestBadHeaderClosesHandle(t *testing.T) {
	src := newSource()
	res := ingest.ImportAll(src, []string{"bad.csv"})
	if !errors.Is(res[0].Err, ingest.ErrBadHeader) {
		t.Fatalf("want ErrBadHeader, got %v", res[0].Err)
	}
	if src.closed != src.opened {
		t.Fatalf("leaked %d handle(s) after a malformed header", src.opened-src.closed)
	}
}

func TestEmptyFileClosesHandle(t *testing.T) {
	src := newSource()
	res := ingest.ImportAll(src, []string{"empty.csv"})
	if res[0].Err == nil {
		t.Fatal("empty file should be an error")
	}
	if src.closed != src.opened {
		t.Fatalf("leaked %d handle(s) after an empty file", src.opened-src.closed)
	}
}

func TestReadErrorClosesHandle(t *testing.T) {
	src := newSource()
	res := ingest.ImportAll(src, []string{"cut.csv"})
	if res[0].Err == nil {
		t.Fatal("truncated transfer should be reported")
	}
	if src.closed != src.opened {
		t.Fatalf("opened %d, closed %d", src.opened, src.closed)
	}
}

func TestOpenFailureDoesNotStopBatch(t *testing.T) {
	src := newSource()
	res := ingest.ImportAll(src, []string{"missing.csv", "good2.csv"})
	if !errors.Is(res[0].Err, os.ErrNotExist) {
		t.Fatalf("want ErrNotExist, got %v", res[0].Err)
	}
	if res[1].Err != nil || res[1].Rows != 1 {
		t.Fatalf("second file should import, got %+v", res[1])
	}
}

func TestNightlyBatchLeavesNothingOpen(t *testing.T) {
	src := newSource()
	var names []string
	for i := 0; i < 30; i++ {
		switch i % 3 {
		case 0:
			names = append(names, "good1.csv")
		case 1:
			names = append(names, "bad.csv")
		default:
			names = append(names, "empty.csv")
		}
	}
	res := ingest.ImportAll(src, names)
	sum := ingest.Summarize(res)
	fmt.Printf("batch of %d: imported=%d failed=%d, handles opened=%d closed=%d\n",
		len(names), sum.Imported, sum.Failed, src.opened, src.closed)
	if src.opened-src.closed != 0 {
		t.Fatalf("%d handles still open after the batch", src.opened-src.closed)
	}
}

func TestSummarize(t *testing.T) {
	src := newSource()
	res := ingest.ImportAll(src, []string{"good1.csv", "bad.csv", "good2.csv"})
	s := ingest.Summarize(res)
	if s.Imported != 2 || s.Failed != 1 || s.Rows != 3 {
		t.Fatalf("got %+v", s)
	}
}
